/// The closing report: every write, then how the daemon restart went.
fn print_setup_report(host: &str, report: &cachet_cli::setup::SetupReport) {
    let mut wrote = report.wrote.iter();
    if let Some(first) = wrote.next() {
        println!("cachet: {host} configured in {}", first.display());
    }
    for path in wrote {
        println!("cachet: wrote {}", path.display());
    }
    match &report.reload {
        cachet_cli::setup::ReloadOutcome::Systemd => {
            println!(
                "cachet: nix-daemon restarted with systemctl, so the new configuration is live"
            );
        }
        cachet_cli::setup::ReloadOutcome::Launchctl(label) => {
            println!("cachet: nix-daemon restarted ({label}), so the new configuration is live");
        }
        cachet_cli::setup::ReloadOutcome::DeterminateInit => {
            println!("cachet: determinate-nixd re-initialized, so the new configuration is live");
        }
        cachet_cli::setup::ReloadOutcome::Failed => {
            eprintln!(
                "cachet: could NOT restart nix-daemon, so the settings above are not in effect yet."
            );

pub fn run_setup(
    paths: &SetupPaths,
    input: &SetupInput,
    run: &Privileged<'_>,
    install: &dyn Fn(&Path, &str, u32) -> Result<(), String>,
) -> Result<SetupReport, CliError> {
    let host = crate::config::host_of(&input.cache_url)?;
    let mut wrote = Vec::new();

    let existing_netrc = std::fs::read_to_string(&paths.netrc).unwrap_or_default();
    let netrc = netrc_replace_block(&existing_netrc, &host, &input.token);
    install(&paths.netrc, &netrc, 0o600).map_err(|failure| {
        CliError(format!(
            "could not write {}: {failure}",
            paths.netrc.display()
        ))
    })?;
    wrote.push(paths.netrc.clone());

    if paths.determinate {
        let existing = std::fs::read_to_string(&paths.determinate_config).ok();
        let config = merge_determinate_config(existing.as_deref())?;
        install(&paths.determinate_config, &config, 0o644).map_err(|failure| {
            CliError(format!(
                "could not write {}: {failure}",
                paths.determinate_config.display()
            ))
        })?;
        wrote.push(paths.determinate_config.clone());
    }

    let existing_conf = std::fs::read_to_string(&paths.nix_custom_conf).unwrap_or_default();
    let netrc_line = if paths.determinate {
        None
    } else {
        Some(paths.netrc.to_string_lossy().into_owned())
    };
    let conf = merge_custom_conf(
        &existing_conf,
        netrc_line.as_deref(),
        &input.cache_url,
        &input.public_key,
        &input.login,
    );
    install(&paths.nix_custom_conf, &conf, 0o644).map_err(|failure| {
        CliError(format!(
            "could not write {}: {failure}",
            paths.nix_custom_conf.display()
        ))
    })?;
    wrote.push(paths.nix_custom_conf.clone());

    let reload = reload_daemon(paths, run);
    Ok(SetupReport { wrote, reload })
}

