                // not in KV costs the next request another renewal,
                // which is a round trip, not an outage.
                let _ = builder.execute().await;
            }
            log::event("info", "auth.github_token_renewed", &[]);
            Ok(renewed)
        }
        Err(_) => {
            let stored = kv
                .get(key)
                .text()
                .await
                .map_err(|_| ClientError::AuthUnavailable)?;
