fn write_kind(req: &Request, method: &Method) -> &'static str {
    match method {
        Method::Put if query_value(req, "partNumber").is_some() => "part",
        Method::Put => "nar",
        Method::Post if query_value(req, "uploadId").is_some() => "complete",
